// ─── Brands ──────────────────────────────────────────────────────────────────
const brands = [
  { slug: "projoy", name: "Projoy", authorized: true },
  { slug: "huawei", name: "Huawei", authorized: true },
  { slug: "tsun", name: "TSUN", authorized: false },
  { slug: "solax", name: "SolaX", authorized: false },
  { slug: "kuvo", name: "KUVO", authorized: false },
  { slug: "scu", name: "SCU", authorized: false },
  { slug: "sine-xcel", name: "Sinexcel", authorized: false },
].map((b) => ({
  _id: `brand-${b.slug}`,
  _type: "brand",
  name: b.name,
  slug: { _type: "slug", current: b.slug },
  authorizedDistributor: b.authorized,
}));

// ─── Products ────────────────────────────────────────────────────────────────
// Helpers for rich product fields (specs, highlights, overview portable-text).
// `_key` values are stable within an array so re-runs don't churn Sanity diffs.
const spec = (label_en, label_th, value, group = "electrical") => ({
  label_en, label_th, value, group,
});

const highlight = (icon, title_en, title_th, body_en, body_th, credential_en, credential_th) => ({
  icon, title_en, title_th, body_en, body_th, credential_en, credential_th,
});

// Convert plain paragraph strings into Sanity portable-text blocks.
const ptParagraphs = (...paragraphs) => paragraphs.map((text, i) => ({
  _type: "block",
  _key: `p${i}`,
  style: "normal",
  markDefs: [],
  children: [{ _type: "span", _key: `s${i}`, text, marks: [] }],
}));

// Stamp stable _key on each array item (Sanity requires _key on array members).
const withKeys = (items, prefix) => items.map((item, i) => ({ ...item, _key: `${prefix}${i}` }));

// Helper: build a product doc with sane defaults. `category` is the slug;
// it's looked up in `categoryIdBySlug` (populated in seed()). Rich fields
// (specs/highlights/overview/compliance) are optional and only emitted when
// provided, so existing minimal entries stay unchanged.
const p = ({
  slug, title, sku, brand, category, en, th,
  exclusive = false, safety = false, rank = 0,
  specs, highlights, overviewEn, overviewTh, compliance,
}) => {
  const catId = category ? categoryIdBySlug.get(category) : undefined;
  if (category && !catId) {
    throw new Error(`Unknown category slug "${category}" for product "${slug}". Available: ${[...categoryIdBySlug.keys()].join(", ")}`);
  }
  const doc = {
    _id: `product-${slug}`,
    _type: "product",
    title,
    slug: { _type: "slug", current: slug },
    sku: sku ?? title,
    brand: brand ? ref(`brand-${brand}`) : undefined,
    category: catId ? ref(catId) : undefined,
    authorized: brand === "projoy" || brand === "huawei",
    exclusive,
    safetyCritical: safety,
    shortDescription_en: en,
    shortDescription_th: th,
    orderRank: rank,
  };
  if (specs?.length) doc.specs = withKeys(specs, `${slug.slice(0, 6)}s`);
  if (highlights?.length) doc.highlights = withKeys(highlights, `${slug.slice(0, 6)}h`);
  if (overviewEn) doc.overview_en = overviewEn;
  if (overviewTh) doc.overview_th = overviewTh;
  if (compliance?.length) doc.compliance = compliance;
  const datasheetId = datasheetIdBySlug.get(slug);
  if (datasheetId) doc.datasheet = ref(datasheetId);
  return doc;
};

