      "ระดับ 6–10 สตริงของ PEFS-EL คือจุดเริ่มต้นระดับอาเรย์ของไลน์สวิตช์ความปลอดภัยสำหรับนักผจญเพลิงของ Projoy — ปรับขนาดสำหรับ Footprint Combiner 250 kW–1 MW ที่ตัวแยก DC ขับด้วยมอเตอร์ตัวเดียวตัด 6 ถึง 10 สตริง PV ขนานในเหตุการณ์การตัดครั้งเดียว คู่มือผู้ใช้ V5.0 (พฤษภาคม 2021) สูงสุดที่ 10 ขั้ว / 5 สตริงในตารางเทคนิคที่เผยแพร่ แต่แคตตาล็อก Projoy P2 รุ่นปรับปรุงและ SKU ของตัวแทนจำหน่าย (เช่น PEFS-EL50H020-P2 = 20 ขั้ว / 10 สตริง) ขยายไลน์ขึ้นไปถึง Footprint 10 สตริงโดยไม่เปลี่ยนวงจรการทำงาน — ไดรฟ์ 100–270 Vac เดียวกัน, กระแสคงสภาพ 30 mA เดียวกัน, การตัดอัตโนมัติ 70°C เดียวกัน, ใบรับรอง EN 60947-3 DC-PV1 เดียวกัน",
      "ตู้แผ่นโลหะ IP65 พร้อมวาล์วระบายอากาศ ติดตั้งบนผนังห้องอินเวอร์เตอร์หรือผนังกั้น Combiner Skid ลอจิกตัวกระตุ้น 3 ทาง (อุณหภูมิแวดล้อม ≥ 70°C, ไฟ AC ดับเกิน 5 วินาที, E-Stop ด้วยตนเอง) เหมือนกับระดับ 1–2 และ 3–5 สตริง — เส้นทางอัพเกรดจากหลังคาที่อยู่อาศัยไปยังโรงไฟฟ้า C&I 1 MW ใช้ขั้นตอนผู้ปฏิบัติงานเดียวกัน, ข้อโต้แย้งการเข้าถึงของหน่วยดับเพลิงเดียวกัน และเส้นทางใบรับรอง TÜV / CE / SAA / UL เดียวกัน ขนาดที่แน่นอน, จำนวนขั้ว และตาราง SKU สำหรับรุ่น 6–10 สตริงเป็น TODO_VERIFY กับแคตตาล็อก Projoy P2 รุ่นล่าสุด — ดาต้าชีท V5.0 ที่รวมอยู่ในซีดนี้แสดงเฉพาะค่าพื้นฐานที่เผยแพร่",
