      "SUN2000-450W-P2 คือ Smart PV Optimizer ของ Huawei สำหรับที่อยู่อาศัย / เชิงพาณิชย์ขนาดเล็ก — เป็นตัวแปลง DC-DC ระดับโมดูลที่ติดตั้งหลังแผงทุกแผงในสตริงที่ผูกกับ SUN2000 และทำให้แต่ละแผงมี MPPT อิสระของตัวเอง เงาบางส่วนจากกำแพงกันตก, มุมเอียงที่ต่างกันระหว่างหลังคาทรงปั้นหยา, แผงที่อายุไม่เท่ากัน และฝุ่นสกปรกจะไม่ฉุดสตริงทั้งหมดลงอีกต่อไป — Huawei ระบุว่าสามารถกู้คืนพลังงานได้สูงสุด 30% บนอาเรย์ที่มีเงาบดบังหนักเมื่อเทียบกับสตริงเดียวกันที่ไม่มีออปติไมเซอร์",
      "ออปติไมเซอร์ตัวเดียวกันนี้ยังบังคับใช้การตัดไฟฉุกเฉินด้วย — การตัดวงจรระดับโมดูลลดแรงดันสตริงไปต่ำกว่า 1 V ต่อออปติไมเซอร์ภายในไม่กี่วินาทีหลังจากกริดดับหรือกด E-Stop ทำงานร่วมกับ AFCI ในตัวอินเวอร์เตอร์ SUN2000 เพื่อให้ผ่านข้อกำหนดความปลอดภัยระดับโมดูล NEC 690.12 และ IEC 60947-3 ตู้ซีล IP68 กลางแจ้งและคอนเนคเตอร์ Stäubli MC4 ติดตั้งหลังเฟรมแผงโดยไม่ต้องใช้ Junction Box ทนมรสุมและความร้อนของไทยโดยไม่ลดทอนประสิทธิภาพ WS Energy เป็นตัวแทนจำหน่ายอย่างเป็นทางการของ Huawei",
